WITH scored AS (SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY customer_id), 4) monthly_fee_share, NTILE(10) OVER (ORDER BY monthly_fee, id) monthly_fee_bucket FROM subscriptions) SELECT id, customer_id, plan, start_date, status, monthly_fee_bucket, CASE WHEN plan RLIKE '^(enterprise|basic)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS plan_zone FROM scored ORDER BY customer_id
